import fs from "node:fs";
import path from "node:path";
import { z } from "zod";

/**
 * Server-side content loaders over the exported JSON in repo /data.
 * Content is generated by ../export_site_data.py — never hand-edit data/.
 * All loaders run at build time (static pages), so plain fs is the right tool.
 */

const DATA_DIR = path.join(process.cwd(), "data");

const QuestionSchema = z.object({
  n: z.number().int().positive(),
  title: z.string(),
  marks: z.string().default(""),
  prompt: z.string(),
  body_md: z.string(),
  has_image: z.boolean().default(false),
  topics: z.array(z.string()).default([]),
});

const PaperSchema = z.object({
  id: z.string(),
  session: z.string(),
  track: z.string(),
  paper: z.string(),
  title: z.string(),
  source: z.string(),
  questions: z.array(QuestionSchema),
});

const IndexQuestionSchema = z.object({
  n: z.number().int(),
  title: z.string(),
  marks: z.string().default(""),
});

const IndexEntrySchema = z.object({
  id: z.string(),
  session: z.string(),
  track: z.string(),
  paper: z.string(),
  title: z.string(),
  count: z.number().int().nonnegative(),
  questions: z.array(IndexQuestionSchema),
});

const ContentIndexSchema = z.object({
  papers: z.array(IndexEntrySchema),
  total_questions: z.number().int().nonnegative(),
  updated: z.string().default(""),
});

export type Question = z.infer<typeof QuestionSchema>;
export type Paper = z.infer<typeof PaperSchema>;
export type PaperIndexEntry = z.infer<typeof IndexEntrySchema>;
export type ContentIndex = z.infer<typeof ContentIndexSchema>;

const TopicQuestionSchema = z.object({
  paper: z.string(),
  n: z.number().int(),
  title: z.string(),
  marks: z.string().default(""),
});

const TopicSchema = z.object({
  slug: z.string(),
  name: z.string(),
  syllabus_area: z.number().int(),
  count: z.number().int().nonnegative(),
  questions: z.array(TopicQuestionSchema),
});

const TopicsFileSchema = z.object({ topics: z.array(TopicSchema) });

export type Topic = z.infer<typeof TopicSchema>;

let cachedTopics: Topic[] | null = null;

export function getTopics(): Topic[] {
  if (cachedTopics) return cachedTopics;
  const parsed = TopicsFileSchema.safeParse(readJson("topics.json"));
  if (!parsed.success) {
    throw new Error(
      `Invalid data/topics.json — run export_site_data.py. ${parsed.error.message}`,
    );
  }
  cachedTopics = parsed.data.topics;
  return cachedTopics;
}

export function getTopic(slug: string): Topic | null {
  return getTopics().find((t) => t.slug === slug) ?? null;
}

export function getTopicSlugs(): string[] {
  return getTopics().map((t) => t.slug);
}

let cachedIndex: ContentIndex | null = null;
const paperCache = new Map<string, Paper | null>();

function readJson(file: string): unknown {
  const raw = fs.readFileSync(path.join(DATA_DIR, file), "utf8");
  return JSON.parse(raw);
}

export function getIndex(): ContentIndex {
  if (cachedIndex) return cachedIndex;
  const parsed = ContentIndexSchema.safeParse(readJson("index.json"));
  if (!parsed.success) {
    throw new Error(
      `Invalid data/index.json — run export_site_data.py. ${parsed.error.message}`,
    );
  }
  cachedIndex = parsed.data;
  return cachedIndex;
}

export function getPaperIds(): string[] {
  return getIndex().papers.map((p) => p.id);
}

export function getPaper(id: string): Paper | null {
  if (paperCache.has(id)) return paperCache.get(id) ?? null;

  const safe = /^\d{2}$/.test(id);
  if (!safe) return null;

  let parsed;
  try {
    parsed = PaperSchema.safeParse(readJson(`papers/${id}.json`));
  } catch {
    paperCache.set(id, null);
    return null;
  }
  if (!parsed.success) {
    throw new Error(
      `Invalid data/papers/${id}.json — run export_site_data.py. ${parsed.error.message}`,
    );
  }
  paperCache.set(id, parsed.data);
  return parsed.data;
}

/** Session groups, newest session first; papers keep their numeric order. */
export function getLibrarySessions(): Array<{
  session: string;
  papers: PaperIndexEntry[];
}> {
  const groups = new Map<string, PaperIndexEntry[]>();
  for (const paper of getIndex().papers) {
    const list = groups.get(paper.session) ?? [];
    list.push(paper);
    groups.set(paper.session, list);
  }
  return [...groups.entries()]
    .sort((a, b) => b[0].localeCompare(a[0]))
    .map(([session, papers]) => ({
      session,
      papers: papers.sort((a, b) => a.id.localeCompare(b.id)),
    }));
}

export function getPaperNeighbours(id: string): {
  prev: PaperIndexEntry | null;
  next: PaperIndexEntry | null;
} {
  const papers = getIndex().papers;
  const i = papers.findIndex((p) => p.id === id);
  if (i === -1) return { prev: null, next: null };
  return {
    prev: i > 0 ? papers[i - 1] : null,
    next: i < papers.length - 1 ? papers[i + 1] : null,
  };
}
